      --panel: rgba(255, 255, 255, 0.9);
      --panel-border: rgba(15, 23, 42, 0.08);
      --text: #0f172a;
      --muted: #64748b;
      --accent: #2563eb;
      --accent-soft: #dbeafe;
      --success: #16a34a;
      --shadow: 0 20px 50px rgba(15, 23, 42, 0.08);
