    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 16px;
      background: #fff;
      transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
      cursor: pointer;
