    .result {
      margin-top: 18px;
      padding: 16px 18px;
      border-radius: 16px;
      background: #ecfdf5;
      color: #166534;
      font-weight: 600;
      display: none;
    }

    .result.show {
      display: block;
    }

    @media (max-width: 640px) {
