 </head>
 <body>
   <main class="quiz-shell">
     <header class="quiz-header">
       <div class="eyebrow">Knowledge check</div>
       <h1>Computer Languages Quiz</h1>
       <p class="subtitle">Select one or more answers for each question. Some questions may have multiple correct choices.</p>
     </header>

     <form id="quiz-form">
       <div class="form-field">
         <h2 class="question-title">1. Which of these are programming languages?</h2>
         <p class="help-text">Choose all that apply.</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q1" value="Python" /><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="HTML" /><span>HTML</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="JavaScript" /><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="SQL" /><span>SQL</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title">2. Which languages are commonly used for web development?</h2>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q2" value="HTML" /><span>HTML</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="CSS" /><span>CSS</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="JavaScript" /><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Ruby" /><span>Ruby</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title">3. Which of these are general-purpose programming languages?</h2>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q3" value="C#" /><span>C#</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Python" /><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Swift" /><span>Swift</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Markdown" /><span>Markdown</span></label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
       </div>

       <div class="result" id="result" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const quizForm = document.getElementById('quiz-form');
     const result = document.getElementById('result');

     const answers = {
       q1: ['Python', 'JavaScript', 'SQL'],
       q2: ['HTML', 'CSS', 'JavaScript'],
       q3: ['C#', 'Python', 'Swift']
     };

     quizForm.addEventListener('submit', (event) => {
       event.preventDefault();

       let score = 0;
       const total = Object.keys(answers).length;

       for (const question of Object.keys(answers)) {
         const selected = [...quizForm.querySelectorAll(`input[name="${question}"]:checked`)].map((input) => input.value).sort();
         const correct = [...answers[question]].sort();
         const isExactMatch = selected.length === correct.length && selected.every((value, index) => value === correct[index]);

         if (isExactMatch) {
           score += 1;
         }
       }

       result.textContent = `You scored ${score} out of ${total}.`;
       result.classList.add('show');
     });
   </script>
 </body>
